def write_file(name, b64content):
    data = base64.b64decode(b64content)
    with open(name, "wb") as f:
        f.write(data)
    print(f"  wrote {name} ({len(data):,} bytes)")


if __name__ == "__main__":
    main()
    write_file("app.js", APP_JS_B64)
    write_file("index.html", INDEX_HTML_B64)
    write_file("style.css", STYLE_CSS_B64)
    print()
